import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Filtering Data","description":"","frontmatter":{},"headers":[],"relativePath":"records-data-access-filtering-and-validation/filtering-data.md","filePath":"records-data-access-filtering-and-validation/filtering-data.md"}`),a={name:`records-data-access-filtering-and-validation/filtering-data.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="filtering-data" tabindex="-1">Filtering Data <a class="header-anchor" href="#filtering-data" aria-label="Permalink to “Filtering Data”">​</a></h1><h2 id="_1-setrange" tabindex="-1">1. SetRange() <a class="header-anchor" href="#_1-setrange" aria-label="Permalink to “1. SetRange()”">​</a></h2><p><code>SetRange()</code> applies a simple filter to a field. You can filter by a single value or a range of values.</p><h3 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to “Syntax”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>RecordVar.SetRange(Field, Value);</span></span>
<span class="line"><span>RecordVar.SetRange(Field, FromValue, ToValue);</span></span></code></pre></div><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Retrieve active products.</span></span>
<span class="line"><span>ProductRec.SetRange(Status, ProductRec.Status::Active);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Retrieve products with inventory between 10 and 100.</span></span>
<span class="line"><span>ProductRec.SetRange(Inventory, 10, 100);</span></span></code></pre></div><p><strong>Use it for simple equality and range filters.</strong></p><h2 id="_2-setfilter" tabindex="-1">2. SetFilter() <a class="header-anchor" href="#_2-setfilter" aria-label="Permalink to “2. SetFilter()”">​</a></h2><p><code>SetFilter()</code> applies more flexible filters using filter expressions.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Inventory greater than 10.</span></span>
<span class="line"><span>ProductRec.SetFilter(Inventory, &#39;&gt;10&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Inventory greater than or equal to 10.</span></span>
<span class="line"><span>ProductRec.SetFilter(Inventory, &#39;&gt;=%1&#39;, 10);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Products whose names start with &#39;Lap&#39;.</span></span>
<span class="line"><span>ProductRec.SetFilter(Name, &#39;Lap*&#39;);</span></span></code></pre></div><p><strong>SetRange vs SetFilter:</strong></p><table tabindex="0"><thead><tr><th>SetRange()</th><th>SetFilter()</th></tr></thead><tbody><tr><td>Simple equality and range filters.</td><td>Flexible filter expressions.</td></tr><tr><td>Accepts values directly.</td><td>Accepts filter expressions and placeholders.</td></tr><tr><td><code>SetRange(Inventory, 10, 100)</code></td><td><code>SetFilter(Inventory, &#39;10..100&#39;)</code></td></tr></tbody></table><p><strong>Important:</strong> <code>SetFilter(Field, &#39;&#39;)</code> does not filter for blank values. Use <code>SetRange(Field, &#39;&#39;)</code> for that.</p><h2 id="_3-filtergroup" tabindex="-1">3. FilterGroup() <a class="header-anchor" href="#_3-filtergroup" aria-label="Permalink to “3. FilterGroup()”">​</a></h2><p><code>FilterGroup()</code> allows us to work with different groups of filters on a record variable.</p><p>Business Central uses filter groups to separate filters applied by different parts of the application.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.FilterGroup(0);</span></span>
<span class="line"><span>ProductRec.SetRange(Status, ProductRec.Status::Active);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ProductRec.FilterGroup(2);</span></span>
<span class="line"><span>ProductRec.SetRange(Inventory, 0, 100);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ProductRec.FilterGroup(0);</span></span></code></pre></div><p>Here:</p><ul><li>Group <code>0</code> is the standard filter group.</li><li>Group <code>2</code> is a separate filter group.</li><li>Filters from different groups are combined when retrieving records.</li><li>Changing the filter group does not remove filters from other groups.</li></ul><p>Some important groups:</p><table tabindex="0"><thead><tr><th>Group</th><th>Purpose</th></tr></thead><tbody><tr><td><code>-1</code></td><td>Cross-column search.</td></tr><tr><td><code>0</code></td><td>Standard filters, including user filters.</td></tr><tr><td><code>1</code></td><td>Global filters.</td></tr><tr><td><code>2</code>–<code>7</code></td><td>Reserved for special application purposes.</td></tr></tbody></table><p>You can also define your own filter groups within the supported range.</p><p><strong>Important:</strong> Always be careful when changing filter groups. Some groups have special system behavior.</p><h2 id="_4-reset" tabindex="-1">4. Reset() <a class="header-anchor" href="#_4-reset" aria-label="Permalink to “4. Reset()”">​</a></h2><p><code>Reset()</code> clears the record variable&#39;s current filters and restores its default view.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.Reset();</span></span></code></pre></div><p>It does more than remove filters:</p><ul><li>Removes all filters.</li><li>Removes marks.</li><li>Resets the current key to the primary key.</li><li>Resets selected fields for loading.</li><li>Restores the default read isolation level.</li><li>Clears AL variables defined on the table.</li></ul><p><strong>Use it when you want to start working with a clean record view.</strong></p><p>It does not delete or modify database records.</p><h2 id="_5-setcurrentkey" tabindex="-1">5. SetCurrentKey() <a class="header-anchor" href="#_5-setcurrentkey" aria-label="Permalink to “5. SetCurrentKey()”">​</a></h2><p><code>SetCurrentKey()</code> specifies the key used to sort records.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.SetCurrentKey(Name);</span></span></code></pre></div><p>You can also specify multiple fields:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.SetCurrentKey(Category, Name);</span></span></code></pre></div><p>This selects a matching table key and requests sorting based on its field sequence.</p><p><strong>Important:</strong> The specified fields must match the beginning of an existing key. The method returns a Boolean indicating whether a matching key was found.</p><p>Example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if ProductRec.SetCurrentKey(Name) then</span></span>
<span class="line"><span>    if ProductRec.FindFirst() then</span></span>
<span class="line"><span>        Message(&#39;%1&#39;, ProductRec.Name);</span></span></code></pre></div><h2 id="_6-filters-and-record-views" tabindex="-1">6. Filters and Record Views <a class="header-anchor" href="#_6-filters-and-record-views" aria-label="Permalink to “6. Filters and Record Views”">​</a></h2><p>A record view describes how records are filtered and sorted.</p><p>It consists primarily of:</p><ul><li>The current key.</li><li>The sorting order.</li><li>The applied filters.</li></ul><p>AL provides two useful methods for working with record views:</p><h3 id="getview" tabindex="-1">GetView() <a class="header-anchor" href="#getview" aria-label="Permalink to “GetView()”">​</a></h3><p>Returns the current view as a text string.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Message(ProductRec.GetView());</span></span></code></pre></div><h3 id="setview" tabindex="-1">SetView() <a class="header-anchor" href="#setview" aria-label="Permalink to “SetView()”">​</a></h3><p>Applies a view specified as a text string.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProductRec.SetView(&#39;SORTING(Name) ORDER(Ascending) WHERE(Status=FILTER(Active))&#39;);</span></span></code></pre></div><p>This sets the sorting and filtering for the record variable.</p><p><strong>Remember:</strong> <code>GetView()</code> retrieves a view, while <code>SetView()</code> applies one.</p><h2 id="_7-putting-everything-together" tabindex="-1">7. Putting Everything Together <a class="header-anchor" href="#_7-putting-everything-together" aria-label="Permalink to “7. Putting Everything Together”">​</a></h2><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    ProductRec: Record Product;</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    // Apply filters.</span></span>
<span class="line"><span>    ProductRec.SetRange(Status, ProductRec.Status::Active);</span></span>
<span class="line"><span>    ProductRec.SetFilter(Inventory, &#39;&gt;0&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Set sorting.</span></span>
<span class="line"><span>    ProductRec.SetCurrentKey(Name);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Retrieve matching products.</span></span>
<span class="line"><span>    if ProductRec.FindSet() then</span></span>
<span class="line"><span>        repeat</span></span>
<span class="line"><span>            Message(&#39;%1 - %2&#39;, ProductRec.Name, ProductRec.Inventory);</span></span>
<span class="line"><span>        until ProductRec.Next() = 0;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // Clear filters and restore default view.</span></span>
<span class="line"><span>    ProductRec.Reset();</span></span>
<span class="line"><span>end;</span></span></code></pre></div><h2 id="quick-comparison" tabindex="-1">Quick Comparison <a class="header-anchor" href="#quick-comparison" aria-label="Permalink to “Quick Comparison”">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Purpose</th></tr></thead><tbody><tr><td><code>SetRange()</code></td><td>Applies simple filters.</td></tr><tr><td><code>SetFilter()</code></td><td>Applies flexible filters.</td></tr><tr><td><code>FilterGroup()</code></td><td>Changes the active filter group.</td></tr><tr><td><code>Reset()</code></td><td>Clears filters and resets the record view and other record state.</td></tr><tr><td><code>SetCurrentKey()</code></td><td>Specifies the sorting key.</td></tr><tr><td><code>GetView()</code></td><td>Retrieves the current record view.</td></tr><tr><td><code>SetView()</code></td><td>Applies a record view.</td></tr></tbody></table><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-setrange-method" target="_blank" rel="noreferrer">Record.SetRange()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-setfilter-method" target="_blank" rel="noreferrer">Record.SetFilter()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-filtergroup-method" target="_blank" rel="noreferrer">Record.FilterGroup()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-reset-method" target="_blank" rel="noreferrer">Record.Reset()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-setcurrentkey-method" target="_blank" rel="noreferrer">Record.SetCurrentKey()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-getview-method" target="_blank" rel="noreferrer">Record.GetView()</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/methods-auto/record/record-setview-method" target="_blank" rel="noreferrer">Record.SetView()</a></li></ul>`,60)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};